import numpy as np
import core_simplex


class Solver:
    def __init__(self):
        # warm-up compilation
        core_simplex._project_simplex(np.array([1.0, 1.2], dtype=np.float64))

    def solve(self, problem, **kwargs):
        y = np.array(problem["y"], dtype=np.float64)
        y = y.ravel()
        x = core_simplex._project_simplex(y)
        return {"solution": x}
